# Simulate Mila's movements and find a sequence that brings her back to the origin after 36 jumps.
def find_sequence():
    # Possible directions for the first move of each jump
    directions = ['L', 'R', 'U', 'D']
    # Directions mapping for the second move of each jump
    dir_map = {'L': ('U', 'D'), 'R': ('U', 'D'), 'U': ('L', 'R'), 'D': ('L', 'R')}

    # Start at (0,0)
    start_point = (0, 0)
    path = [start_point]

    def move(x, y, d1, d2, n):
        # First move
        if d1 == 'L':
            x -= 1
        elif d1 == 'R':
            x += 1
        elif d1 == 'U':
            y += 1
        elif d1 == 'D':
            y -= 1

        # Second move
        if d2 == 'L':
            x -= n
        elif d2 == 'R':
            x += n
        elif d2 == 'U':
            y += n
        elif d2 == 'D':
            y -= n

        return x, y

    # Brute force search for a valid sequence
    from itertools import product
    for dirs in product(directions, repeat=36):
        x, y = 0, 0
        for i, d1 in enumerate(dirs):
            d2 = dir_map[d1][i%2]  # alternate between the two possible second directions
            x, y = move(x, y, d1, d2, i+1)
            path.append((x, y))
        if (x, y) == start_point:
            return path
        path = [start_point]

path = find_sequence()
